css:
.lsm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsm-root,.lsm-root *,.lsm-root *::before,.lsm-root *::after{box-sizing:border-box}
.lsm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsm-root img{display:block;border:0;max-width:none}
.lsm-root [hidden]{display:none!important}
.lsm-root .n32_434{align-content:stretch;display:flex;align-items:center;justify-content:space-between;position:relative;flex-shrink:0;width:100%}
.lsm-root .n32_420{align-content:stretch;display:flex;gap:8px;align-items:center;position:relative;flex-shrink:0}
.lsm-root .n32_416{height:17px;position:relative;flex-shrink:0;width:2px;background-image:linear-gradient(0deg, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 0%, transparent) 0%, var(--wa-bg, rgb(255, 255, 255)) 52%, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 99%, transparent) 53%, color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 0%, transparent) 100%)}
.lsm-root .n32_414{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #fff);white-space:nowrap;width:37px}
.lsm-root .n32_433{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;line-height:0;place-items:start;position:relative;flex-shrink:0}
.lsm-root .n32_421{grid-column:1;height:27px;margin-left:0;margin-top:0;pointer-events:none;position:relative;border-radius:100px;grid-row:1;width:76px}
.lsm-root .x98{position:absolute;background-color:var(--wa-ok, #55b05d);inset:0;border-radius:100px}
.lsm-root .x99{position:absolute;inset:0;border-radius:inherit;box-shadow:inset 0px 5px 5px 0px rgba(17,64,29,0.4)}
.lsm-root .n32_425{grid-column:1;margin-left:52px;margin-top:3px;position:relative;grid-row:1;width:21px;height:21px}
.lsm-root .x100{position:absolute;inset:0 -9.52% -19.05% -9.52%}
.lsm-root .x101{display:block;max-width:none;width:100%;height:100%}
.lsm-root .n30_386{word-break:break-word;grid-column:1;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:14px;margin-left:8px;margin-top:7px;font-style:normal;position:relative;grid-row:1;color:var(--wa-ok, #33683f);font-size:12px;white-space:nowrap;width:18px}
.lsm-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsm-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsm-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsm-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsm-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsm-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsm-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsm-root[data-theme="light"] .n32_416{background-image:linear-gradient(0deg, color-mix(in srgb, var(--wa-surface, rgb(90 95 104)) 0%, transparent) 0%, var(--wa-surface, #5a5f68) 52%, color-mix(in srgb, var(--wa-surface, rgb(90 95 104)) 99%, transparent) 53%, color-mix(in srgb, var(--wa-surface, rgb(90 95 104)) 0%, transparent) 100%)}
.lsm-root[data-theme="light"] .n32_414{color:var(--wa-text, #10231d)}
